edits.newText:
double _radiusFor(
  List<double> spectrum,
  double maxAllowed, {
  required double minAllowed,
}) {
  if (maxAllowed <= 0) return 0.0;

  final effectiveMax = min(config.maxDotSize, maxAllowed);
  final effectiveMin = min(minAllowed, effectiveMax);

  if (spectrum.isEmpty) return effectiveMin;

  var bass = 0.0;
  for (var i = 0; i < min(spectrum.length, 3); i++) {
    bass = max(bass, spectrum[i]);
  }

  final r = effectiveMin +
      bass * bass * config.sensitivity * (effectiveMax - effectiveMin);
  return r.clamp(effectiveMin, effectiveMax);
}

