@override
Widget build(BuildContext context) {
  final palette = Theme.of(context).extension<AppPalette>()!;
  final typography = Theme.of(context).extension<AppTypography>()!;

  // read (not watch): the dot animates off [spectrumListenable] below, so this
  // widget must NOT rebuild on every controller notify.
  final player = context.read<PlaybackController>();

  return LayoutBuilder(
    builder: (context, constraints) {
      const double textTopPadding = 12.0;

      // B-020: when song-info is enabled, reserve enough top space for the
      // worst-case 2-line (Artist + Song) typography so the pulsing dot
      // never intersects it.
      final reservedTop = config.showSongInfo
          ? (textTopPadding +
              (typography.heroSize * config.textScale) * 1.18 * 2 +
              8.0 +
              (typography.heroSize * heroSongSizeFactor * config.textScale) *
                  1.18 *
                  2)
          : 0.0;

      final clampedReservedTop = reservedTop.clamp(0.0, constraints.maxHeight);
      final remainingH = max(constraints.maxHeight - clampedReservedTop, 0.0);

      final maxAllowed =
          min(constraints.maxWidth, remainingH) / 2;
      final minAllowed = min(config.minDotSize, maxAllowed);

      return BaseHeroContainer(
        child: Stack(
          children: [
            if (!config.showSongInfo)
              // Pulsing dot — always centered. Only this subtree repaints per
              // spectrum frame (RepaintBoundary-isolated).
              Center(
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: player.spectrumListenable,
                    builder: (context, _) {
                      final r = _radiusFor(
                        player.spectrumData,
                        maxAllowed,
                        minAllowed: minAllowed,
                      );
                      return Container(
                        width: r * 2,
                        height: r * 2,
                        decoration: BoxDecoration(
                          color: palette.fgPrimary
                              .withValues(alpha: config.dotOpacity),
                          shape: BoxShape.circle,
                        ),
                      );
                    },
                  ),
                ),
              )
            else
              // When the title overlay is enabled, center the dot in the
              // remaining space below it.
              Positioned(
                left: 0,
                right: 0,
                top: clampedReservedTop,
                bottom: 0,
                child: Center(
                  child: RepaintBoundary(
                    child: AnimatedBuilder(
                      animation: player.spectrumListenable,
                      builder: (context, _) {
                        final r = _radiusFor(
                          player.spectrumData,
                          maxAllowed,
                          minAllowed: minAllowed,
                        );
                        return Container(
                          width: r * 2,
                          height: r * 2,
                          decoration: BoxDecoration(
                            color: palette.fgPrimary
                                .withValues(alpha: config.dotOpacity),
                            shape: BoxShape.circle,
                          ),
                        );
                      },
                    ),
                  ),
                ),
              ),

            // Optional song-info overlay pinned to the top of the hero band (B-020), above the dot.
            if (config.showSongInfo)
              Positioned(
                left: 0,
                right: 0,
                top: textTopPadding,
                child: Opacity(
                  opacity: config.textOpacity.clamp(0.0, 1.0),
                  child: HeroTitleBlock(textScale: config.textScale),
                ),
              ),
          ],
        ),
      );
    },
  );
}
